-- LEARN(sql.subqueries-ctes.modifying): RETURNING turns a write into rows the rest of the statement can read.
CREATE TABLE test_runs (
  id        int PRIMARY KEY,
  test_case text NOT NULL,
  ran_on    date NOT NULL,
  passed    boolean NOT NULL
);
CREATE TABLE test_runs_archive (LIKE test_runs INCLUDING ALL);
INSERT INTO test_runs VALUES
  (1, 'Login', '2026-10-02', true), (2, 'Login', '2026-11-12', false),
  (3, 'Export', '2026-10-20', true), (4, 'Export', '2026-11-13', true);

-- Move October's runs to the archive in one statement: a run can't be
-- deleted without being archived, or archived twice.
WITH moved AS (
  DELETE FROM test_runs
  WHERE ran_on < date '2026-11-01'
  RETURNING *
)
INSERT INTO test_runs_archive
SELECT * FROM moved;

SELECT 'live' AS place, id FROM test_runs
UNION ALL
SELECT 'archive', id FROM test_runs_archive
ORDER BY place, id;

-- A parent and its children in one round trip: generated ids flow from
-- the first INSERT's RETURNING into the second.
CREATE TABLE requirements (
  id   int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code text NOT NULL UNIQUE
);
CREATE TABLE test_cases (
  id             int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  requirement_id int NOT NULL REFERENCES requirements,
  title          text NOT NULL
);
WITH req AS (
  INSERT INTO requirements (code) VALUES ('REQ-EXPORT') RETURNING id
), tests AS (
  INSERT INTO test_cases (requirement_id, title)
  SELECT req.id, t.title
  FROM req, (VALUES ('CSV header row'), ('UTF-8 with BOM for Excel')) AS t(title)
  RETURNING requirement_id, id, title
)
SELECT * FROM tests ORDER BY id;

files.examples/02_one_snapshot.sql:
CREATE TABLE test_cases (id int PRIMARY KEY, title text NOT NULL, status text NOT NULL);
INSERT INTO test_cases VALUES
  (1, 'Login', 'failed'), (2, 'Logout', 'passed'), (3, 'Export', 'failed');

-- Every part of the statement reads the same snapshot, taken before any of
-- it ran. The table still shows the old status; RETURNING shows the new one.
WITH reopened AS (
  UPDATE test_cases SET status = 'retest'
  WHERE status = 'failed'
  RETURNING id, status
)
SELECT t.id, t.status AS in_table, r.status AS returned
FROM test_cases t
LEFT JOIN reopened r ON r.id = t.id
ORDER BY t.id;

-- The next statement sees the change.
SELECT id, status FROM test_cases ORDER BY id;

-- Get-or-create a tag. If the INSERT adds a row, only RETURNING can show it;
-- if the tag already exists, the INSERT returns nothing and the SELECT finds it.
CREATE TABLE tags (id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text UNIQUE NOT NULL);
INSERT INTO tags (name) VALUES ('security');

WITH ins AS (
  INSERT INTO tags (name) VALUES ('kvkk') ON CONFLICT (name) DO NOTHING
  RETURNING id, 'created' AS how
)
SELECT id, how FROM ins
UNION ALL
SELECT id, 'found' FROM tags WHERE name = 'kvkk';

WITH ins AS (
  INSERT INTO tags (name) VALUES ('security') ON CONFLICT (name) DO NOTHING
  RETURNING id, 'created' AS how
)
SELECT id, how FROM ins
UNION ALL
SELECT id, 'found' FROM tags WHERE name = 'security';

-- Data-modifying WITH is allowed only on the top-level statement.
SELECT count(*)
FROM (WITH gone AS (DELETE FROM tags RETURNING id) SELECT id FROM gone) AS s;

files.examples/03_audit.sql:
CREATE TABLE test_cases (id int PRIMARY KEY, title text NOT NULL, status text NOT NULL);
CREATE TABLE status_changes (
  test_case_id int  NOT NULL REFERENCES test_cases,
  old_status   text NOT NULL,
  new_status   text NOT NULL
);
INSERT INTO test_cases VALUES
  (1, 'Login', 'failed'), (2, 'Logout', 'passed'), (3, 'Export', 'retest');

-- Change rows and write the audit trail in one statement. RETURNING old.*
-- and new.* (PG 18) hand both versions of each row to the next step.
WITH changed AS (
  UPDATE test_cases SET status = 'passed'
  WHERE id IN (1, 2, 3) AND status <> 'passed'
  RETURNING id, old.status AS old_status, new.status AS new_status
), logged AS (
  INSERT INTO status_changes (test_case_id, old_status, new_status)
  SELECT id, old_status, new_status FROM changed
  RETURNING *
)
SELECT * FROM logged ORDER BY test_case_id;

-- Logout was already passed: not updated, so not logged.
SELECT id, status FROM test_cases ORDER BY id;
